import { useIntl } from 'react-intl';

import abiConnectQrcodeImage from 'assets/img/ConnectionsCreativityOverview/abi_connect_qrcode.png';
import { SubPillarCard } from 'components/SubPillarCard';

import {
  StyledConnectAppContent,
  StyledConnectAppQrcodeImage,
} from './ConnectSection.styles';

export const ConnectAppCard = () => {
  const { formatMessage } = useIntl();

  return (
    <SubPillarCard
      title={formatMessage({
        id: 'ConnectionsCreativity.Home.connect.connectApp.title',
      })}
      description={formatMessage({
        id: 'ConnectionsCreativity.Home.connect.connectApp.description',
      })}
    >
      <StyledConnectAppContent>
        <StyledConnectAppQrcodeImage
          src={abiConnectQrcodeImage}
          alt={formatMessage({
            id: 'ConnectionsCreativity.Home.connect.connectApp.altQrcode',
          })}
        />
      </StyledConnectAppContent>
    </SubPillarCard>
  );
};
